static void slider_event_callback(lv_event_t * e) {
	lv_obj_t * obj = (lv_obj_t*) lv_event_get_target(e);
	lv_obj_t * obj_label = (lv_obj_t*) lv_event_get_user_data(e);
	char buf[8];
	lv_snprintf(buf, sizeof(buf), "%d%%", (int)lv_slider_get_value(obj));
	lv_label_set_text(obj_label, buf);
	LV_LOG_USER("Slider changed to %d%%", (int)lv_slider_get_value(obj));
	ledcWrite(CYD_LED_RED, map((int)lv_slider_get_value(obj), 0, 100, 255, 0));
	sliderValue4 = String((int)lv_slider_get_value(obj));
	notifyClients(getWidgetValues());
}

