void lv_create_main_gui(void) {
	// Create a toggle switch (toggle_switch)
	lv_obj_t * toggle_switch = lv_switch_create(lv_screen_active());
	lv_obj_add_event_cb(toggle_switch, toggle_switch_event_handler, LV_EVENT_ALL, NULL);
	lv_obj_add_flag(toggle_switch, LV_OBJ_FLAG_EVENT_BUBBLE);
	lv_obj_align(toggle_switch, LV_ALIGN_TOP_MID, 0, 50);
	// Create a slider aligned in the center bottom of the TFT display
	lv_obj_t * slider = lv_slider_create(lv_screen_active());
	lv_obj_align(slider, LV_ALIGN_CENTER, 0, 20);
	lv_slider_set_range(slider, 0, 100);

	// Create a label below the slider to display the current slider value
	lv_obj_t * slider_label = lv_label_create(lv_screen_active());
	lv_label_set_text(slider_label, "0%");
	lv_obj_align_to(slider_label, slider, LV_ALIGN_CENTER, 0, 40);
	lv_obj_add_event_cb(slider, slider_event_callback,
LV_EVENT_VALUE_CHANGED, slider_label);
}

