	// Configure the ON/OFF LED
	pinMode(CYD_LED_BLUE, OUTPUT);
	digitalWrite(CYD_LED_BLUE, HIGH);

	// Configure LED PWM functionalities and attach the channel to the GPIO to be controlled
	ledcAttachChannel(CYD_LED_RED, freq, resolution, ledChannel);
	ledcWrite(CYD_LED_RED, 255);

	I2CBME.begin(I2C_SDA, I2C_SCL, 100000);
	bool status;
	// Passing a &Wire2 to set custom I2C ports
	status = bme.begin(0x76, &I2CBME);
	if (!status) {
		Serial.println("Could not find a valid BME280 sensor, check wiring!");
		while (1);
	}
	initLittleFS();
	initWiFi();
	initWebSocket();
	// Route for root / web page
	server.on("/", HTTP_GET, [](AsyncWebServerRequest *request){
		request->send(LittleFS, "/index.html", "text/html",false);
	});
	server.serveStatic("/", LittleFS, "/");
	// Start server
	server.begin();

	// Start LVGL
	lv_init();
	// Register print function for debugging
	lv_log_register_print_cb(log_print);
	// Start the SPI for the touchscreen and init the touchscreen
	touchscreenSPI.begin(XPT2046_CLK, XPT2046_MISO, XPT2046_MOSI, XPT2046_CS);
	touchscreen.begin(touchscreenSPI);
	// Set the Touchscreen rotation in landscape mode
	// Note: in some displays, the touchscreen might be upside down
	// so you might need to set the rotation to 0: touchscreen.setRotation(0);
	touchscreen.setRotation(2);

	// Create a display object
	lv_display_t * disp;
	// Initialize the TFT display using the TFT_eSPI library
	disp = lv_tft_espi_create(SCREEN_WIDTH, SCREEN_HEIGHT, draw_buf, sizeof(draw_buf));
	lv_display_set_rotation(disp, LV_DISPLAY_ROTATION_270);

	// Initialize an LVGL input device object (Touchscreen)
	lv_indev_t * indev = lv_indev_create();
	lv_indev_set_type(indev, LV_INDEV_TYPE_POINTER);
	// Set the callback function to read Touchscreen input
	lv_indev_set_read_cb(indev, touchscreen_read);

	// Function to draw the GUI
	lv_create_main_gui();
}
void loop() {
	ws.cleanupClients();
	lv_task_handler();  // let the GUI do its work
	lv_tick_inc(5);     // tell LVGL how much time has passed
	delay(5);           // let this time pass
	unsigned long currentMillis = millis();
	if (currentMillis - previousMillis >= interval) {
		previousMillis = currentMillis;  // save the last time that chart was updated
		updateBMEReadings();  // read the latest BME280 readings
		notifyClients(getWidgetValues());
		// notify all connected clients with the latest values
	}
}
