+ "." + lv_version_minor() + "." + lv_version_patch();
	Serial.begin(115200);
	Serial.println(LVGL_Arduino);

	// Start Serial 2 with the defined RX and TX pins and a baud rate of 9600
	gpsSerial.begin(GPS_BAUD, SERIAL_8N1, RXD2, TXD2);
	Serial.println("Serial 2 started at 9600 baud rate");
	if (!SD.begin(SD_CS)) {
		Serial.println("Card Mount Failed");
		return;
	}
	uint8_t cardType = SD.cardType();
	if (cardType == CARD_NONE) {
		Serial.println("No SD card attached");
		return;
	}

	// If the gps_data.txt file doesn't exist, create a file on the SD card and write the header
	File file = SD.open("/gps_data.txt");
	if(!file) {
		Serial.println("gps_data.txt file doesn't exist");
		Serial.println("Creating file...");
		writeFile(SD, "/gps_data.txt",
		       "longitude,latitude,altitude,speed,hdop,satellites,date,utc_time\r\n");
	} else {
		Serial.println("gps_data.txt file already exists");
	}
	file.close();

	// Start LVGL
	lv_init();
	// Register print function for debugging
	lv_log_register_print_cb(log_print);

	// Create a display object
	lv_display_t * disp;
	// Initialize the TFT display using the TFT_eSPI library
	disp = lv_tft_espi_create(SCREEN_WIDTH, SCREEN_HEIGHT, draw_buf, sizeof(draw_buf));
	lv_display_set_rotation(disp, LV_DISPLAY_ROTATION_270);

	// Function to draw the GUI
	lv_create_main_gui();
}

void loop() {
	lv_task_handler();  // let the GUI do its work
	lv_tick_inc(5);     // tell LVGL how much time has passed
	delay(5);           // let this time pass

	// This sketch displays information every time a new sentence is correctly encoded  
	unsigned long start = millis();

	while (millis() - start < 10000) {
		while (gpsSerial.available() > 0) {
			//char c = gpsSerial.read();   // Read one character at a time
			// Print raw NMEA sentences to the Serial Monitor
			//Serial.write(c);
			gps.encode(gpsSerial.read());
		}
		if (gps.location.isUpdated()) {
			Serial.print("LONG: ");
			longitude = String(gps.location.lng(), 6);
			Serial.println(longitude);
			Serial.print("LAT: ");
			latitude = String(gps.location.lat(), 6);
			Serial.println(latitude);
			Serial.print("ALT (min)= ");
			altitude = String(gps.altitude.meters(), 2);
			Serial.println(altitude);
			Serial.print("SPEED (km/h) = ");
			speed = String(gps.speed.kmph(), 2);
			Serial.println(speed);
			Serial.print("HDOP = ");
			hdop = String(gps.hdop.value() / 100.0, 2);
			Serial.println(hdop);
			Serial.print("Satellites = ");
			satellites = String(gps.satellites.value());
			Serial.println(satellites);
			Serial.print("Time in UTC: ");
			Serial.println(String(gps.date.year()) + "-" + String(gps.date.month())
			      + "-" + String(gps.date.day()) + "," + String(gps.time.hour()) + ":"
			      + String(gps.time.minute()) + ":" + String(gps.time.second()));
			current_date = String(gps.date.year()) + "-" + String(gps.date.month())
			      + "-" + String(gps.date.day());
			Serial.println(current_date);
			utc_time = String(format_time(gps.time.hour())) + ":"
			           + String(format_time(gps.time.minute())) + ":"
			           + String(format_time(gps.time.second()));
			Serial.println(utc_time);
			Serial.println("");
		}
	}
}
