// Variables to store the latest values
String weather_description;
String temperature_c;
String temperature_f;
String humidity;
String wind_speed; 
String current_date;
String current_time;
String region_country;

// Touchscreen pins
#define XPT2046_IRQ 36   // T_IRQ
#define XPT2046_MOSI 32  // T_DIN
#define XPT2046_MISO 39  // T_OUT
#define XPT2046_CLK 25   // T_CLK
#define XPT2046_CS 33    // T_CS

SPIClass touchscreenSPI = SPIClass(VSPI);
XPT2046_Touchscreen touchscreen(XPT2046_CS, XPT2046_IRQ);

#define SCREEN_WIDTH 240
#define SCREEN_HEIGHT 320

// Touchscreen coordinates: (x, y) and pressure (z)
int x, y, z;

#define DRAW_BUF_SIZE (SCREEN_WIDTH * SCREEN_HEIGHT / 10 * (LV_COLOR_DEPTH / 8))
uint32_t draw_buf[DRAW_BUF_SIZE / 4];

// If logging is enabled, it will inform the user about what is happening in the library
void log_print(lv_log_level_t level, const char * buf) {
	LV_UNUSED(level);
	Serial.println(buf);
	Serial.flush();
}

// Get the Touchscreen data
void touchscreen_read(lv_indev_t * indev, lv_indev_data_t * data) {
	// Checks if Touchscreen was touched, and prints X, Y and Pressure (Z)
	if(touchscreen.tirqTouched() && touchscreen.touched()) {
		// Get Touchscreen points
		TS_Point p = touchscreen.getPoint();
		// Advanced Touchscreen calibration
		float alpha_x, beta_x, alpha_y, beta_y, delta_x, delta_y;
		// REPLACE WITH YOUR OWN CALIBRATION VALUES
		// https://RandomNerdTutorials.com/touchscreen-calibration/
		alpha_x = -0.000;
		beta_x = 0.090;
		delta_x = -33.771;
		alpha_y = 0.066;
		beta_y = 0.000;
		delta_y = -14.632;

		x = alpha_y * p.x + beta_y * p.y + delta_y;
		// clamp x between 0 and SCREEN_WIDTH - 1
		x = max(0, x);
		x = min(SCREEN_WIDTH - 1, x);

		y = alpha_x * p.x + beta_x * p.y + delta_x;
		// clamp y between 0 and SCREEN_HEIGHT - 1
		y = max(0, y);
		y = min(SCREEN_HEIGHT - 1, y);

		// Basic Touchscreen calibration points with map function to the correct width and height
		//x = map(p.x, 200, 3700, 1, SCREEN_WIDTH);
		//y = map(p.y, 240, 3800, 1, SCREEN_HEIGHT);

		z = p.z;

		data->state = LV_INDEV_STATE_PRESSED;

		// Set the coordinates
		data->point.x = x;
		data->point.y = y;
	} else {
		data->state = LV_INDEV_STATE_RELEASED;
	}
}

