void lv_create_main_gui(void) {
	// Create a Button
	lv_obj_t * button = lv_button_create(lv_screen_active());
	lv_obj_set_size(button, 120, 50);    // Set the button size
	lv_obj_align(button, LV_ALIGN_CENTER, 0, 0);

	// Add a label to the button
	lv_obj_t * button_label = lv_label_create(button);
	lv_label_set_text(button_label, "Click here!");    // Set the text label
	lv_obj_center(button_label);

	lv_obj_t * text_label_counter = lv_label_create(lv_screen_active());
	lv_label_set_text(text_label_counter, "Counter: 0");
	lv_obj_align(text_label_counter, LV_ALIGN_BOTTOM_MID, 0, -50);

	lv_obj_add_event_cb(button, button_event_cb, LV_EVENT_ALL, text_label_counter);
}

void connectToWifi() {
	Serial.println("Connecting to Wi-Fi...");
	WiFi.begin(wifi, password);
}

void connectToMqtt() {
	Serial.println("Connecting to MQTT...");
	mqttClient.connect();
}

void WiFiEvent(WiFiEvent_t event) {
	Serial.printf("[WiFi-event] event: %d\n", event);
	switch(event) {
		case ARDUINO_EVENT_WIFI_STA_GOT_IP:
			Serial.println("WiFi connected");
			Serial.println("IP address: ");
			Serial.println(WiFi.localIP());
			connectToMqtt();
			break;
		case ARDUINO_EVENT_WIFI_STA_DISCONNECTED:
			Serial.println("WiFi lost connection");
			xTimerStop(mqttReconnectTimer, 0);
			xTimerStart(wifiReconnectTimer, 0);
			break;
	}
}

void onMqttConnect(bool sessionPresent) {
	Serial.println("Connected to MQTT.");
	/*Serial.print("Session present: ");
	Serial.println(sessionPresent);*/
}

void onMqttDisconnect(AsyncMqttClientDisconnectReason reason) {
	Serial.println("Disconnected from MQTT.");
	if (WiFi.isConnected()) {
		xTimerStart(mqttReconnectTimer, 0);
	}
}

void onMqttPublish(uint16_t packetId) {
	/*Serial.println("Publish acknowledged.");
	Serial.print("  packetId: ");
	Serial.println(packetId);*/
}

