// Get the latest BME280 readings and update the screen
void updateBMEReadings() {
	#if TEMP_CELSIUS
		float bme_temp = bme.readTemperature();
		const char degree_symbol[] = "\u00B0C";
	#else
		float bme_temp = 1.8 * bme.readTemperature() + 32;
		const char degree_symbol[] = "\u00B0F";
	#endif
	String bme_temp_text = "Temperature: " + String(bme_temp) + degree_symbol;
	temperature = String(bme_temp);
	lv_label_set_text(temperature_label, bme_temp_text.c_str());

	float bme_humi = bme.readHumidity();
	humidity = String(bme_humi);
	String bme_humi_text = "Humidity: " + String(bme_humi) + "%";
	lv_label_set_text(humidity_label, bme_humi_text.c_str());
}

String getWidgetValues(){
	// Prepare JSON object to notify all connected clients with the latest values
	StaticJsonDocument<256> json_array;
	json_array["switchState17"] = switchState17;
	json_array["sliderValue4"] = sliderValue4;
	json_array["temperature"] = temperature;
	json_array["humidity"] = humidity;

	// Serialize the JSON object to a string
	String json_string;
	serializeJson(json_array, json_string);
	Serial.println(json_string);   // Print the JSON string for debugging
	return json_string;
}

void notifyClients(String state) {
	ws.textAll(state);
}

// This function checks incoming messages from connected clients
void handleWebSocketMessage(void *arg, uint8_t *data, size_t len) {
	AwsFrameInfo *info = (AwsFrameInfo*)arg;
	if (info->final && info->index == 0 && info->len == len && info->opcode==WS_TEXT) {
		data[len] = 0;
		message = (char*)data;
		int split_index = message.indexOf(':');
		String widget_name = message.substring(0, split_index);
		String widget_value = message.substring(split_index + 1, split_index+1 - message.length());
		// Checks if the message from the web page has "switchState17"
		// which will be used to turn the GPIO ON or OFF
		if (widget_name == "switchState17") {
			switchState17 = widget_value;
			digitalWrite(CYD_LED_BLUE, !widget_value.toInt());
			if (widget_value == "1") {
				lv_obj_add_state(toggle_switch, LV_STATE_CHECKED);
			} else {
				lv_obj_remove_state(toggle_switch, LV_STATE_CHECKED);
			}
			notifyClients(getWidgetValues());
		}
		// Checks if the message from the web page has "sliderValue4"
		// which will be used to adjust the PWM signal
		if (widget_name == "sliderValue4") {
			sliderValue4 = widget_value;
			ledcWrite(CYD_LED_RED, map(widget_value.toInt(), 0, 100, 255, 0));
			lv_label_set_text(slider_label, String(widget_value+"%").c_str());
			lv_slider_set_value(slider, widget_value.toInt(), LV_ANIM_ON);
			notifyClients(getWidgetValues());
		}
		// Checks if the message from the web page has "getWidgetValues" 
		// which will be used to return the current widget values
		if (widget_name == "getWidgetValues") {
			updateBMEReadings();
			notifyClients(getWidgetValues());
		}
	}
}
